WITH mine AS ( SELECT message_id, provider_label_id, seq, label_present FROM email_gmail_pending_label_writes WHERE message_id = ANY($1) AND write_id = $2 ), next AS ( SELECT DISTINCT ON (c.message_id, c.provider_label_id) c.seq, mine.label_present FROM email_gmail_pending_label_writes c JOIN mine ON c.message_id = mine.message_id AND c.provider_label_id = mine.provider_label_id AND c.seq > mine.seq ORDER BY c.message_id, c.provider_label_id, c.seq ), falls_back AS ( UPDATE email_gmail_pending_label_writes c SET label_present_before = next.label_present FROM next WHERE c.seq = next.seq ) DELETE FROM email_gmail_pending_label_writes c USING mine WHERE c.message_id = mine.message_id AND c.provider_label_id = mine.provider_label_id AND c.seq <= mine.seq
